326			}
327		}
328		if len(receiptEvents) != 1 || receiptEvents[0].ObjectID != x.ID ||
329			receiptEvents[0].ActorID != rcv.ID || !receiptEvents[0].OccurredAt.Equal(succeededAt) {
330			t.Fatalf("receipt events after reopen = %+v, want exactly one for %q at %v",
331				receiptEvents, x.ID, succeededAt)
332		}
333	}
334

