1	package clinical
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"testing"
8		"time"
9	)
10	
11	// TestRetrySucceedsDespiteSaveFailure 覆盖“交换已成功保存后，本地保存条件\n// 不可用”时的重试行为：同使用者同请求号同参数必须成功返回正式保存的\n// 交换（含已登记回执与冻结包），不落盘、不重新打包；不同参数仍报\n// ErrConflict；另一使用者或新请求号的首次创建仍按既有规则校验并在\n// 保存失败时返回实际错误、不占用请求号。
12	func TestRetrySucceedsDespiteSaveFailure(t *testing.T) {
13		dir := t.TempDir()
14		clk := &fakeClock{t: time.Date(2026, 6, 1, 9, 0, 0, 0, time.UTC)}
15		s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
16		if err != nil {
17			t.Fatal(err)
18		}
19		defer s.Close()
20	
21		p, _ := s.RegisterPatient(doc, "患者")
22		e, _ := s.AddEncounter(doc, p.ID, time.Time{})
23		rd, _ := s.CreateDraft(doc, p.ID, e.ID, Diagnosis, "诊断v1")
24		if _, err := s.ActivateRecord(doc, rd.ID); err != nil {
25			t.Fatal(err)
26		}
27		ro, _ := s.CreateDraft(doc, p.ID, e.ID, Order, "医嘱v1")
28		if _, err := s.ActivateRecord(doc, ro.ID); err != nil {
29			t.Fatal(err)
30		}
31		a, _ := s.Grant(doc, p.ID, rcv.ID,
32			[]Scope{{EncounterID: e.ID, Category: Diagnosis}, {EncounterID: e.ID, Category: Order}},
33			clk.t.Add(-time.Hour), clk.t.Add(48*time.Hour))
34		// 另一条有效授权，供“另一使用者首次创建恰逢保存失败”场景使用。
35		a2, _ := s.Grant(doc, p.ID, rcv.ID,
36			[]Scope{{EncounterID: e.ID, Category: Diagnosis}},
37			clk.t.Add(-time.Hour), clk.t.Add(48*time.Hour))
38	
39		x, err := s.CreateExchange(doc, p.ID, rcv.ID, a.ID, []ID{rd.ID, ro.ID}, "req-x")
40		if err != nil {
41			t.Fatal(err)
42		}
43		// 接收方登记拒绝回执。
44		if _, err := s.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptRejected, "原因"); err != nil {
45			t.Fatal(err)
46		}
47		withReceipt, err := s.GetExchange(doc, p.ID, x.ID)
48		if err != nil {
49			t.Fatal(err)
50		}
51	
52		// 之后记录被更正、授权被撤回：重试不得重新打包。
53		if _, err := s.CorrectRecord(doc, rd.ID, 1, "诊断v2", "更正"); err != nil {
54			t.Fatal(err)
55		}
56		if err := s.Revoke(doc, p.ID, a.ID); err != nil {
57			t.Fatal(err)
58		}
59	
60		// 制造本地保存失败。
61		dataPath := filepath.Join(dir, dataName)
62		backup := dataPath + ".saved"
63		if err := os.Rename(dataPath, backup); err != nil {
64			t.Fatal(err)
65		}
66		if err := os.Mkdir(dataPath, 0o755); err != nil {
67			t.Fatal(err)
68		}
69		defer func() {
70			os.Remove(dataPath)
71			os.Rename(backup, dataPath)
72		}()
73	
74		// 同参数重试（乱序+重复）：成功返回原交换，含已登记回执。
75		got, err := s.CreateExchange(doc, p.ID, rcv.ID, a.ID, []ID{ro.ID, rd.ID, ro.ID}, "req-x")
76		if err != nil {
77			t.Fatalf("retry with same params during save failure: %v", err)
78		}
79		assertExchangeMatches(t, got, withReceipt, "retry during save failure")
80		if got.Status != ExchangeRejected || got.Receipt == nil || got.Receipt.Reason != "原因" {
81			t.Fatalf("receipt lost on retry: %+v", got)
82		}
83		// 包内容仍是创建时固化的 v1，不是更正后的 v2。
84		for _, r := range got.Package.Records {
85			if r.RecordID == rd.ID && r.Content != "诊断v1" {
86				t.Fatalf("retry repackaged current version: %+v", r)
87			}
88		}
89		// 返回副本独立：篡改不影响库内。
90		tamperExchangeResult(&got)
91		g2, _ := s.GetExchange(doc, p.ID, x.ID)
92		assertExchangeMatches(t, g2, withReceipt, "store after tampering retry result")
93	
94		// 不同参数：ErrConflict，而不是保存错误。
95		if _, err := s.CreateExchange(doc, p.ID, rcv.ID, a.ID, []ID{rd.ID}, "req-x"); !errors.Is(err, ErrConflict) {
96			t.Fatalf("different params err = %v, want ErrConflict", err)
97		}
98	
99		// 另一内部使用者沿用相同请求号：视为首次创建，保存失败返回实际错误。
100		if _, err := s.CreateExchange(doc2, p.ID, rcv.ID, a2.ID, []ID{rd.ID}, "req-x"); err == nil {
101			t.Fatal("other actor create during save failure must fail")
102		} else if errors.Is(err, ErrConflict) || errors.Is(err, ErrAccessDenied) {
103			t.Fatalf("save failure surfaced as business error: %v", err)
104		}
105	
106		// 无对应成功交换的新请求号：保存失败返回实际错误，不占用请求号。
107		if _, err := s.CreateExchange(doc, p.ID, rcv.ID, a2.ID, []ID{rd.ID}, "req-new"); err == nil {
108			t.Fatal("first create during save failure must fail")
109		} else if errors.Is(err, ErrConflict) || errors.Is(err, ErrAccessDenied) {
110			t.Fatalf("save failure surfaced as business error: %v", err)
111		}
112	
113		// 恢复保存条件：新请求号未被失败尝试占用，可成功创建。
114		if err := os.Remove(dataPath); err != nil {
115			t.Fatal(err)
116		}
117		if err := os.Rename(backup, dataPath); err != nil {
118			t.Fatal(err)
